INSERT INTO dbo.tgh_admin_unit (CountryId, ParentId, LevelType, Code, Status, SortOrder, CreatedAt, CreatedBy, UpdatedAt, UpdatedBy)

SELECT @vnId, NULL, N'Province', NULL, 1, 0, SYSUTCDATETIME(), N'system', SYSUTCDATETIME(), N'system'

FROM @prov ORDER BY RowNo;



;WITH p AS (

    SELECT RowNo, ProvinceName FROM @prov

), u AS (

    SELECT ROW_NUMBER() OVER (ORDER BY AdminUnitId) AS RowNo, AdminUnitId

    FROM dbo.tgh_admin_unit WHERE CountryId = @vnId AND LevelType = N'Province'

)

INSERT INTO dbo.tgh_admin_unit_lang (AdminUnitId, Lang, Name, CreatedAt, CreatedBy, UpdatedAt, UpdatedBy)

SELECT u.AdminUnitId, N'vi', p.ProvinceName, SYSUTCDATETIME(), N'system', SYSUTCDATETIME(), N'system'

FROM p JOIN u ON p.RowNo = u.RowNo;



