INSERT INTO dbo.tgh_admin_unit (CountryId, ParentId, LevelType, Code, Status, SortOrder, CreatedAt, CreatedBy, UpdatedAt, UpdatedBy)

SELECT @vnId, p.AdminUnitId, N'Ward', NULL, 1, 0, SYSUTCDATETIME(), N'system', SYSUTCDATETIME(), N'system'

FROM @ward w

JOIN dbo.tgh_admin_unit_lang p ON p.Lang = N'vi' AND p.Name = w.ProvinceName

JOIN dbo.tgh_admin_unit u ON u.AdminUnitId = p.AdminUnitId AND u.CountryId = @vnId AND u.LevelType = N'Province'

ORDER BY w.RowNo;



;WITH wsrc AS (

    SELECT RowNo, ProvinceName, WardName, ROW_NUMBER() OVER (PARTITION BY ProvinceName ORDER BY RowNo) AS Rn

    FROM @ward

), wunit AS (

    SELECT u.AdminUnitId, p.Name AS ProvinceName, ROW_NUMBER() OVER (PARTITION BY p.Name ORDER BY u.AdminUnitId) AS Rn

    FROM dbo.tgh_admin_unit u

    JOIN dbo.tgh_admin_unit_lang p ON p.AdminUnitId = u.ParentId AND p.Lang = N'vi'

    WHERE u.CountryId = @vnId AND u.LevelType = N'Ward'

)

INSERT INTO dbo.tgh_admin_unit_lang (AdminUnitId, Lang, Name, CreatedAt, CreatedBy, UpdatedAt, UpdatedBy)

SELECT u.AdminUnitId, N'vi', w.WardName, SYSUTCDATETIME(), N'system', SYSUTCDATETIME(), N'system'

FROM wsrc w JOIN wunit u ON w.ProvinceName = u.ProvinceName AND w.Rn = u.Rn;

SET NOCOUNT ON;



DECLARE @vnId INT = (SELECT CountryId FROM dbo.tgh_country WHERE Iso2 = N'VN');

IF @vnId IS NULL BEGIN RAISERROR(N'VN not found', 16, 1); RETURN; END;



DELETE l FROM dbo.tgh_admin_unit_lang l JOIN dbo.tgh_admin_unit u ON l.AdminUnitId = u.AdminUnitId WHERE u.CountryId = @vnId AND u.LevelType IN (N'Province', N'Ward');

DELETE FROM dbo.tgh_admin_unit WHERE CountryId = @vnId AND LevelType IN (N'Province', N'Ward');



