INSERT INTO dbo.adm_menu_lang (MenuId, Lang, Title, Url, SeoTitle, SeoDescription, SeoKeywords, SlugId, Status, SortOrder, CreatedAt, CreatedBy, UpdatedAt, UpdatedBy)
