           WHEN N'transfer_vehicles' THEN N'Xe'
           WHEN N'vehicle_brands' THEN N'Hãng xe'
           WHEN N'vehicle_models' THEN N'Model xe'
           WHEN N'transfer_drivers' THEN N'Tài x?'
